<main id="content" class="avela-shell avela-page avela-reading"><?php while ( have_posts() ) : the_post(); ?><article <?php post_class(); ?>><p class="avela-eyebrow"><?php echo esc_html( get_the_date() ); ?></p><h1 class="avela-page-title"><?php the_title(); ?></h1><?php the_post_thumbnail( 'large' ); ?><div class="avela-entry"><?php the_content(); wp_link_pages(); ?></div><?php the_post_navigation(); ?></article><?php if ( comments_open() || get_comments_number() ) { comments_template(); } endwhile; ?></main><?php get_footer(); ?>
